def _seq(row: Mapping[str, Any] | None) -> int:
    try:
        return int((row or {}).get("seq", -1))
    except (TypeError, ValueError):
        return -1


def _summary(row: Mapping[str, Any] | None) -> dict[str, Any]:
    if not row:
        return {}
    keys = {
        "seq", "type", "timestamp", "postId", "authorHandle", "active", "text",
        "topic", "query", "view", "handle", "total", "id", "outbound", "createdAt",
    }
    return {key: row.get(key) for key in keys if key in row}


